<?php require_once dirname(__DIR__).'/src/bootstrap.php';$group=$_GET['blood_group']??'';if($group!==''&&!in_array($group,blood_groups(),true))$group='';$pageTitle='Donor Coverage';require dirname(__DIR__).'/src/templates/header.php';?>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
<section class="section"><div class="container"><div class="eyebrow">Sri Lanka donor coverage</div><h1 class="section-title">Available donor coverage by district</h1><p class="section-sub">Counts are aggregated and small counts are suppressed. This public view does not expose precise donor locations or contact information.</p><div class="toolbar"><form method="get"><select name="blood_group"><option value="">All blood groups</option><?php foreach(blood_groups() as $g):?><option value="<?=e($g)?>" <?=$group===$g?'selected':''?>><?=e($g)?></option><?php endforeach;?></select><button class="btn btn-sm">Filter</button></form></div><div id="coverage-map" class="map"></div></div></section>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const centers={Ampara:[7.2912,81.6724],Anuradhapura:[8.3114,80.4037],Badulla:[6.9934,81.055],Batticaloa:[7.717,81.7],Colombo:[6.9271,79.8612],Galle:[6.0535,80.221],Gampaha:[7.0873,80.0144],Hambantota:[6.1429,81.1212],Jaffna:[9.6615,80.0255],Kalutara:[6.5854,79.9607],Kandy:[7.2906,80.6337],Kegalle:[7.2513,80.3464],Kilinochchi:[9.3803,80.377],Kurunegala:[7.4863,80.3647],Mannar:[8.981,79.9044],Matale:[7.4675,80.6234],Matara:[5.9549,80.555],Monaragala:[6.8728,81.3507],Mullaitivu:[9.2671,80.8142],'Nuwara Eliya':[6.9497,80.7891],Polonnaruwa:[7.9403,81.0188],Puttalam:[8.0408,79.8394],Ratnapura:[6.7056,80.3847],Trincomalee:[8.5874,81.2152],Vavuniya:[8.7514,80.4971]};const map=L.map('coverage-map').setView([7.8731,80.7718],7);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);fetch(<?=json_encode(url('api/district-coverage.php'.($group?'?blood_group='.urlencode($group):'')))?>).then(r=>r.json()).then(rows=>rows.forEach(r=>{const c=centers[r.district];if(!c)return;const n=r.count===null?1:Number(r.count);L.circleMarker(c,{radius:Math.min(24,7+Math.sqrt(n)*2),weight:2,fillOpacity:.58}).addTo(map).bindPopup(`<strong>${r.district}</strong><br>Available donors: ${r.count===null?'fewer than 3':r.count}`)}));</script>
